window.MG_LAZY_DATA["data/lazy/owner-resources/b459-5de7407d13d887d5.json"]={sha256:"5de7407d13d887d5a90c6f442c6b3207f2ab1039a15cc8818273241318dce084",value:{"sources":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-urban-green","title":"綠色基礎設施類型","titleEn":"Types of Green Infrastructure","url":"https://www.epa.gov/green-infrastructure/types-green-infrastructure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-swmm","title":"暴雨逕流與低衝擊開發模型","titleEn":"Storm Water Management Model (SWMM)","url":"https://www.epa.gov/water-research/storm-water-management-model-swmm","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"media":{"courses":[{"courseId":"b459","videos":[],"guides":[{"id":"b459-v17-practice","title":"工程操作與定量驗證手冊","titleEn":"Engineering actions and quantitative verification","concept":"以「街樹根域、雨水與人行空間協調」為主線，依序完成十個專題單元。學徒在場景中辨識設備、列出邊界、重算明示的教學算例、比較量測與模型，最後診斷故障並交付證據。每一單元保留機制、算例、驗證與失效四種學習任務。","conceptEn":"Follow coordinate root volume, stormwater and pedestrian space through ten technical units. Identify equipment in the scene, define boundaries, reproduce explicitly hypothetical examples, compare measurements with models, and diagnose faults before handing over evidence. Each unit contains mechanism, calculation, verification and failure tasks.","procedure":["在「樹穴集水分區」的教學模型或試算表中先重現 2.55 m3，再依驗證任務改動一個輸入、保留其餘條件。對照「集水分配不均會一株過濕另一株缺水。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「根域有效土量」的教學模型或試算表中先重現 9 m3，再依驗證任務改動一個輸入、保留其餘條件。對照「把不連通土穴相加會高估可用根域。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「根域孔隙與含氣量」的教學模型或試算表中先重現 0.1 m3/m3，再依驗證任務改動一個輸入、保留其餘條件。對照「將最大蓄水當唯一目標可能使根域缺氧。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「沉砂與入口保護」的教學模型或試算表中先重現 0.255 kg/event，再依驗證任務改動一個輸入、保留其餘條件。對照「沉積抬高後會把後續逕流導離樹穴。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「地表蓄水與根頸」的教學模型或試算表中先重現 0.6 m3，再依驗證任務改動一個輸入、保留其餘條件。對照「蓄水邊緣過高可能使根頸長期淹水。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「蒸散與灌溉缺口」的教學模型或試算表中先重現 0.12 m3/day，再依驗證任務改動一個輸入、保留其餘條件。對照「全年雨量充足不代表乾季每一天有足夠水。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「結構土與壓實取捨」的教學模型或試算表中先重現 1600 kg/m3，再依驗證任務改動一個輸入、保留其餘條件。對照「只提高壓實度可能損害根系與入滲。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「鹽分累積」的教學模型或試算表中先重現 0.4 kg/m3，再依驗證任務改動一個輸入、保留其餘條件。對照「只測雨水低鹽可能漏掉路面與介質鹽源。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「樹根與地下管線」的教學模型或試算表中先重現 0.75 fraction，再依驗證任務改動一個輸入、保留其餘條件。對照「施工後才發現管線會迫使切斷根域連通。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「生長與水工共同驗收」的教學模型或試算表中先重現 0.875 fraction，再依驗證任務改動一個輸入、保留其餘條件。對照「以樹葉茂密掩蓋路面隆起會漏掉使用風險。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。"],"procedureEn":["In the teaching model or spreadsheet for tree-pit catchment, first reproduce 2.55 m3, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Unequal capture can waterlog one tree and dry another.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for effective rooting volume, first reproduce 9 m3, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Adding isolated pockets overstates usable root space.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for root-zone pores and aeration, first reproduce 0.1 m3/m3, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Maximizing storage alone can deprive roots of oxygen.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for sediment and inlet protection, first reproduce 0.255 kg/event, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Accumulated sediment can divert later runoff away.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for surface storage and root collar, first reproduce 0.6 m3, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"An excessively high storage rim can submerge the root collar.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for evapotranspiration and irrigation deficit, first reproduce 0.12 m3/day, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Adequate annual rain does not ensure daily dry-season supply.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for structural soil and compaction trade-offs, first reproduce 1600 kg/m3, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Increasing compaction alone can impair roots and infiltration.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for salt accumulation, first reproduce 0.4 kg/m3, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Low-salt rain measurements miss road and soil salt sources.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for roots and buried utilities, first reproduce 0.75 fraction, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Late utility discovery can sever planned soil continuity.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for joint vegetation and hydraulic review, first reproduce 0.875 fraction, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Dense foliage can hide pavement heave concerns.\" and submit baseline and changed values, units, and one measurement that distinguishes them."],"evidence":["描繪相鄰兩樹穴集水界線。","將地下管線畫入剖面並更新連通土量。","提高含水率並比較含氣孔隙。","檢查入口與樹幹基部的沉積分布。","在剖面標示根頸與最高模擬水位。","用一週乾天資料檢查儲水是否耗盡。","同時比較承載試驗與入滲、含氣孔隙。","將蒸散造成的水量減少列入鹽收支。","比較移動管線與改變樹穴的兩個剖面方案。","將缺水、積水、根浮與入口堵塞分開記錄。"],"evidenceEn":["Map catchment boundaries between adjacent pits.","Add utilities to the section and update connected soil volume.","Raise water content and compare air-filled porosity.","Inspect deposition at the inlet and trunk base.","Mark root collar and maximum simulated water level in section.","Use a dry week to check depletion of stored water.","Compare bearing tests with infiltration and air-filled porosity.","Include evapotranspiration water loss in the salt balance.","Compare sections with relocated utilities or redesigned pits.","Record drought stress, ponding, root heave and inlet blockage separately."],"pitfalls":["集水分配不均會一株過濕另一株缺水。","把不連通土穴相加會高估可用根域。","將最大蓄水當唯一目標可能使根域缺氧。","沉積抬高後會把後續逕流導離樹穴。","蓄水邊緣過高可能使根頸長期淹水。","全年雨量充足不代表乾季每一天有足夠水。","只提高壓實度可能損害根系與入滲。","只測雨水低鹽可能漏掉路面與介質鹽源。","施工後才發現管線會迫使切斷根域連通。","以樹葉茂密掩蓋路面隆起會漏掉使用風險。"],"pitfallsEn":["Unequal capture can waterlog one tree and dry another.","Adding isolated pockets overstates usable root space.","Maximizing storage alone can deprive roots of oxygen.","Accumulated sediment can divert later runoff away.","An excessively high storage rim can submerge the root collar.","Adequate annual rain does not ensure daily dry-season supply.","Increasing compaction alone can impair roots and infiltration.","Low-salt rain measurements miss road and soil salt sources.","Late utility discovery can sever planned soil continuity.","Dense foliage can hide pavement heave concerns."],"sourceIds":["v17s-urban-green","v17s-urban-swmm"],"sources":[{"id":"v17s-urban-green","title":"綠色基礎設施類型","titleEn":"Types of Green Infrastructure","url":"https://www.epa.gov/green-infrastructure/types-green-infrastructure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-swmm","title":"暴雨逕流與低衝擊開發模型","titleEn":"Storm Water Management Model (SWMM)","url":"https://www.epa.gov/water-research/storm-water-management-model-swmm","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"simulationOnly":true,"scope":"公開原理與資料支持的原創教學。算例中的輸入為明示教學假設，非該設施實測或操作設定。此處任務在離線模型完成，不能作為現場設計、飲用水合格或設備操作許可。","scopeEn":"Original teaching based on public principles and sources. Numerical inputs are explicit teaching assumptions, not site measurements or operating setpoints. Tasks use offline models and do not certify field design, potable-water compliance or equipment operation."}]}]},"related":{"courses":[{"courseId":"b459","overview":"跨單元連結與比較練習","overviewEn":"Cross-process connections and comparisons","related":[{"id":"b415","title":"首爾清溪川復育","titleEn":"Seoul Cheonggyecheon restoration","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"首爾代表點","nameEn":"Seoul reference point","country":"南韓","countryEn":"South Korea","lat":37.57,"lon":126.98,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":126.98,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]},{"id":"b416","title":"新加坡碧山—宏茂橋公園河川復育","titleEn":"Bishan–Ang Mo Kio Park river restoration","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"新加坡","nameEn":"Singapore","country":"新加坡","countryEn":"Singapore","lat":1.35,"lon":103.82,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":103.82,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]}],"references":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-urban-green","title":"綠色基礎設施類型","titleEn":"Types of Green Infrastructure","url":"https://www.epa.gov/green-infrastructure/types-green-infrastructure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-swmm","title":"暴雨逕流與低衝擊開發模型","titleEn":"Storm Water Management Model (SWMM)","url":"https://www.epa.gov/water-research/storm-water-management-model-swmm","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}]}]},"places":{"courses":[{"courseId":"b459","place":{"name":"美國EPA總部：方法資料來源機構（非實廠）","nameEn":"US EPA headquarters: methodology source institution (not a process plant)","country":"美國","countryEn":"United States","lat":38.8941,"lon":-77.0298,"coordinateScope":"近似機構所在區域位置；依公開地址作教材地圖代表點，非建物入口、實廠、實測或導航位置。","coordinateScopeEn":"Approximate institution-area location inferred from its public address for the teaching map; not a building entrance, process plant, surveyed point or navigation coordinate.","locationSourceUrl":"https://www.epa.gov/aboutepa/visiting-epa-headquarters","locationVerified":"2026-10-23","lng":-77.0298},"summary":"本課以來源所列的技術指引與研究為閱讀脈絡，並非重建某一設施的工程沿革；算例、數據與場景參數皆為原創教學假設。比較舊方法與感測、控制、資源回收整合的方法時，先固定處理功能及系統邊界，再評估效率與可靠度。","summaryEn":"The cited technical guidance and research provide a reading pathway, not the engineering history of a particular facility. Examples, data and scene parameters are original teaching assumptions. When comparing conventional methods with integrated sensing, control and resource recovery, hold the treatment function and system boundary fixed before assessing efficiency and reliability.","history":[{"year":"工程背景","title":"街道植栽樹穴海綿設計","titleEn":"Sponge-tree pits for streets","text":"本課以來源所列的技術指引與研究為閱讀脈絡，並非重建某一設施的工程沿革；算例、數據與場景參數皆為原創教學假設。比較舊方法與感測、控制、資源回收整合的方法時，先固定處理功能及系統邊界，再評估效率與可靠度。","textEn":"The cited technical guidance and research provide a reading pathway, not the engineering history of a particular facility. Examples, data and scene parameters are original teaching assumptions. When comparing conventional methods with integrated sensing, control and resource recovery, hold the treatment function and system boundary fixed before assessing efficiency and reliability."}],"connection":"以「街樹根域、雨水與人行空間協調」為主線，依序完成十個專題單元。學徒在場景中辨識設備、列出邊界、重算明示的教學算例、比較量測與模型，最後診斷故障並交付證據。每一單元保留機制、算例、驗證與失效四種學習任務。","connectionEn":"Follow coordinate root volume, stormwater and pedestrian space through ten technical units. Identify equipment in the scene, define boundaries, reproduce explicitly hypothetical examples, compare measurements with models, and diagnose faults before handing over evidence. Each unit contains mechanism, calculation, verification and failure tasks.","references":[{"id":"v17s-urban-green","title":"綠色基礎設施類型","titleEn":"Types of Green Infrastructure","url":"https://www.epa.gov/green-infrastructure/types-green-infrastructure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-swmm","title":"暴雨逕流與低衝擊開發模型","titleEn":"Storm Water Management Model (SWMM)","url":"https://www.epa.gov/water-research/storm-water-management-model-swmm","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"sourceIds":["v17s-urban-green","v17s-urban-swmm"]}]},"vendors":{"courses":[],"vendors":[]}}};
